// Compare today's values with the last run, kept in workflow static data.
// Swap `rates` for any API field (stock level, price list, order count) and keep the rest.
const threshold = 0.5; // percent
const today = $input.first().json;
const store = $getWorkflowStaticData('global');
const prev = store.lastRates || {};
const moves = [];
for (const [symbol, rate] of Object.entries(today.rates)) {
  const old = prev[symbol];
  if (!old) continue;
  const change = (rate - old) / old * 100;
  if (Math.abs(change) >= threshold) {
    moves.push({ symbol, old, new: rate, change_pct: Number(change.toFixed(2)) });
  }
}
store.lastRates = today.rates;
store.lastDate = today.date;
return [{ json: { date: today.date, base: today.base, moves, hasMoves: moves.length > 0 } }];
